const payload = $json.body?.event ? $json.body : $json;
const lead = payload.lead || {};
const answers = lead.answers || {};
const scoring = payload.scoring || {};
const routing = payload.routing || {};
const lifecycle = payload.lifecycle || {};
const rag = payload.rag || {};
const clean = (value, fallback = '') => value === undefined || value === null ? fallback : String(value);
const score = clean(scoring.score, 'pending').toLowerCase();
const event = clean(payload.event, score === 'pending' ? 'lead.created' : 'lead.qualified');
const createdAt = clean(lead.createdAt, new Date().toISOString());
const qualifiedAt = clean(lifecycle.qualifiedAt);
const contact = clean(lead.contact);
const eventId = clean(payload.eventId, `${event}:${lead.id || contact || 'unknown'}:${qualifiedAt || createdAt}`);
const row = {
  event,
  eventId,
  emittedAt: clean(payload.emittedAt, new Date().toISOString()),
  createdAt,
  qualifiedAt,
  name: clean(lead.name),
  school: clean(lead.school),
  contact,
  need: clean(lead.need),
  goal: clean(answers.goal),
  level: clean(answers.level),
  start: clean(answers.start),
  format: clean(answers.format),
  budget: clean(answers.budget),
  contactTime: clean(answers.contactTime),
  score,
  points: Number(scoring.points || 0),
  status: clean(scoring.status, score === 'pending' ? 'intake' : 'new'),
  nextAction: clean(scoring.nextAction),
  source: clean(lead.source),
  managerAlert: clean(routing.managerAlert),
  followUp: clean(routing.followUp),
  ragSources: Array.isArray(rag.sources) ? rag.sources.join('|') : clean(rag.sources),
};
const signal = [row.goal, row.start, row.budget].filter(Boolean).join(' / ') || row.need || 'No signal yet';
const intake = ['New intake lead', `Name: ${row.name || 'Unknown'}`, `School: ${row.school || 'Unknown'}`, `Contact: ${row.contact || 'No contact'}`, `Need: ${row.need || 'Not specified'}`, 'Status: waiting for qualification answers', 'Next action: continue qualification in Telegram.'].join('\n');
const qualified = [`${row.score.toUpperCase()} lead`, `Name: ${row.name || 'Unknown'}`, `School: ${row.school || 'Unknown'}`, `Contact: ${row.contact || 'No contact'}`, `Goal: ${row.goal || 'Not answered'}`, `Level: ${row.level || 'Not answered'}`, `Start: ${row.start || 'Not answered'}`, `Format: ${row.format || 'Not answered'}`, `Budget: ${row.budget || 'Not answered'}`, `Contact time: ${row.contactTime || 'Not answered'}`, `Signal: ${signal}`, `Next action: ${row.nextAction || 'Review lead'}`].join('\n');
const hot = ['HOT lead - call first', qualified].join('\n\n');
const warm = ['WARM lead - write today', qualified].join('\n\n');
const cold = ['COLD lead - add to nurture', qualified].join('\n\n');
const followUpTitles = { qualification: 'Wait for bot qualification', call_window: 'Create call window follow-up', fit_questions: 'Send fit questions follow-up', intro_material: 'Send nurture material' };
const followUpDue = { qualification: 'after bot completion', call_window: 'today', fit_questions: 'today', intro_material: 'within 3 days' };
return [{ json: { ...row, row, eventId, contactKey: contact.toLowerCase().replace(/\s+/g, ''), isIntake: event === 'lead.created' || score === 'pending', isQualified: event === 'lead.qualified', isHot: score === 'hot', isWarm: score === 'warm', isCold: score === 'cold', telegram: { intake, hot, warm, cold, manager: qualified }, followUpTask: { type: row.followUp || 'unrouted', title: followUpTitles[row.followUp] || 'Review lead', dueHint: followUpDue[row.followUp] || 'manual review', status: 'planned', owner: row.managerAlert || 'manager' } } }];

const store = $getWorkflowStaticData('global');
store.skillbridgeSeenEvents = store.skillbridgeSeenEvents || {};
const key = $json.eventId;
const seenAt = store.skillbridgeSeenEvents[key];
const isDuplicate = Boolean(seenAt);
if (!isDuplicate) store.skillbridgeSeenEvents[key] = new Date().toISOString();
return [{ json: { ...$json, isDuplicate, duplicateSeenAt: seenAt || '' } }];
